<template>
<div class="office-page search-page" v-loading="loading">
  <header class="office-toolbar"><h2>搜索</h2><form class="search-form" @submit.prevent="search"><el-input v-model="keyword" clearable aria-label="搜索内容" placeholder="搜索团队内容" list="search-suggestions" @input="suggest"/><datalist id="search-suggestions"><option v-for="item in suggestions" :key="item" :value="item"/></datalist><el-button native-type="submit" type="primary" circle title="搜索"><span class="material-symbols-outlined">search</span></el-button></form></header>
  <el-radio-group v-model="scope" @change="search" aria-label="搜索范围"><el-radio-button v-for="(label,key) in scopes" :key="key" :value="key">{{ label }}</el-radio-button></el-radio-group>
  <div class="search-filters"><el-date-picker v-model="from" type="date" value-format="YYYY-MM-DD" placeholder="开始日期" aria-label="开始日期"/><el-date-picker v-model="to" type="date" value-format="YYYY-MM-DD" placeholder="结束日期" aria-label="结束日期"/><el-select v-model="creator" clearable filterable placeholder="创建者" aria-label="创建者"><el-option v-for="member in members" :key="member.userId" :label="member.userName" :value="String(member.userId)"/></el-select><el-input v-model="tag" placeholder="标签" clearable aria-label="标签筛选"/><el-button @click="search">筛选</el-button><el-button text @click="reset">重置</el-button></div>
  <div v-if="history.length" class="search-history"><span class="office-muted">最近搜索</span><button v-for="item in history" :key="item" class="office-link" @click="keyword=item;search()">{{ item }}</button><el-button text size="small" @click="clearHistory">清空</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <p class="office-muted result-count">{{ results.length }} 条结果</p>
  <article v-for="r in results" :key="r.type+r.id" class="search-result"><span class="material-symbols-outlined result-icon">{{ icons[r.type]||'description' }}</span><div class="result-body"><button class="office-link result-title" @click="open(r)"><template v-for="(part,index) in highlight(r.title||r.name||r.realName||r.username,applied)" :key="index"><mark v-if="part.match">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></button><p v-if="r.snippet&&r.type!=='message'" class="result-snippet"><template v-for="(part,index) in highlight(snippet(r.snippet),applied)" :key="index"><mark v-if="part.match">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></p><small class="office-muted">{{ r.creatorName||'' }} <span v-if="r.createdAt"> · {{ String(r.createdAt).replace('T',' ').slice(0,16) }}</span><span v-if="r.sessionName"> · {{ r.sessionName }}</span><span v-if="r.tags"> · {{ tagsText(r.tags) }}</span></small></div><el-tag size="small" type="info">{{ scopes[r.type]||'成员' }}</el-tag></article>
  <el-empty v-if="!loading&&!results.length" :description="keyword?'没有找到匹配内容':'搜索团队中的文档、任务和消息'"/>
</div>
</template>
<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import request from '@/utils/request'
import {useWorkspaceStore} from '@/stores/workspace'
import {highlight} from './highlight'
const route=useRoute(),router=useRouter(),workspace=useWorkspaceStore(),keyword=ref(String(route.query.q||'')),scope=ref(''),results=ref<any[]>([]),loading=ref(false),from=ref(''),to=ref(''),creator=ref(''),tag=ref(''),members=ref<any[]>([]),history=ref<string[]>([]),suggestions=ref<string[]>([]),error=ref(''),applied=ref('')
const scopes:Record<string,string>={'':'全部',document:'文档',sheet:'表格',mindmap:'导图',whiteboard:'白板',task:'任务',message:'消息',user:'成员'},icons:Record<string,string>={task:'task_alt',user:'person',message:'chat',sheet:'table_chart',mindmap:'account_tree',whiteboard:'draw'}
let key='',sequence=0,suggestSequence=0,timer:ReturnType<typeof setTimeout>|undefined,disposed=false
function persist(){try{if(key)localStorage.setItem(key,JSON.stringify(history.value))}catch{}}
async function search(){const term=keyword.value.trim(),ticket=++sequence;if(!term){results.value=[];loading.value=false;error.value='';return}if(from.value&&to.value&&from.value>to.value){error.value='开始日期不能晚于结束日期';loading.value=false;return}loading.value=true;error.value='';try{const r:any=await request.get('/search/global',{params:{keyword:term,scope:scope.value,from:from.value||undefined,to:to.value||undefined,creatorId:creator.value||undefined,tag:tag.value||undefined}});if(ticket!==sequence||disposed)return;results.value=r.data;applied.value=term;history.value=[term,...history.value.filter(x=>x!==term)].slice(0,12);persist()}catch(e:any){if(ticket===sequence)error.value=e.message||'搜索失败'}finally{if(ticket===sequence)loading.value=false}}
function suggest(){if(timer)clearTimeout(timer);const term=keyword.value.trim(),ticket=++suggestSequence;suggestions.value=[];if(!term)return;timer=setTimeout(async()=>{try{const r:any=await request.get('/search/suggest',{params:{keyword:term}});if(!disposed&&ticket===suggestSequence)suggestions.value=r.data}catch{}},300)}
function clearHistory(){history.value=[];persist()}
function reset(){from.value='';to.value='';creator.value='';tag.value='';search()}
function snippet(value:string){const text=String(value).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(),index=text.toLocaleLowerCase().indexOf(applied.value.toLocaleLowerCase());return (index>60?'…':'')+text.slice(Math.max(0,index-60),Math.max(0,index-60)+220)}
function tagsText(value:any){try{return (typeof value==='string'?JSON.parse(value):value).join(' / ')}catch{return value}}
function open(r:any){router.push(r.type==='message'?{path:'/im',query:{session:r.sessionId,message:r.id}}:r.type==='task'?'/tasks?task='+r.id:r.type==='user'?'/space/manage':r.type==='sheet'?'/sheets/'+r.id:r.type==='mindmap'?'/mindmap/'+r.id:r.type==='whiteboard'?'/whiteboard/'+r.id:'/documents/'+r.id)}
onMounted(async()=>{try{const [user,team]:any[]=await Promise.all([request.get('/user/info'),request.get(`/space/${workspace.spaceId}/members`)]);members.value=team.data;key=`search-history:${user.data.userId}:${workspace.spaceId}`;try{const saved=JSON.parse(localStorage.getItem(key)||'[]');history.value=Array.isArray(saved)?saved.filter(x=>typeof x==='string').slice(0,12):[]}catch{}}finally{await search()}})
onBeforeUnmount(()=>{disposed=true;sequence++;suggestSequence++;if(timer)clearTimeout(timer)})
</script>
<style scoped>
.search-page{max-width:1100px;margin:0 auto}.search-form{display:flex;gap:8px;width:min(440px,100%)}.search-filters{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);padding:var(--space-4) 0}.search-filters :deep(.el-date-editor),.search-filters .el-select,.search-filters>.el-input{width:170px;flex:none}.search-history{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12px}.search-history .office-link{font-size:12px}.result-count{font-size:12px}.search-result{display:flex;align-items:flex-start;gap:14px;padding:18px 0;border-bottom:1px solid var(--c-border)}.search-result:hover{background:var(--c-bg)}.result-icon{color:var(--c-brand);font-size:22px;padding-top:3px}.result-body{min-width:0;flex:1}.result-title{text-align:left;font-size:14px;line-height:1.6;overflow-wrap:anywhere}.result-snippet{margin:6px 0;font-size:13px;color:var(--c-text-secondary);overflow-wrap:anywhere}.result-body small{display:block;font-size:11px;margin-top:5px;overflow-wrap:anywhere}mark{background:var(--c-warning-light);color:var(--c-text);border-radius:2px}.search-page>.el-radio-group{display:flex;flex-wrap:wrap;gap:0}@media(max-width:600px){.search-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.search-filters :deep(.el-date-editor),.search-filters .el-select,.search-filters>.el-input{width:100%;min-width:0}.search-form{width:100%}.search-result{gap:8px}}
</style>
